"""Scan for fraction patterns: N/M and standalone ½, ¼, ¾."""

import re

# Slash fraction and standalone symbols: half (U+00BD), quarter (U+00BC), three-quarters (U+00BE)
FRACTION_SLASH_RE = re.compile(r"\b\d+/\d+\b")
FRACTION_QUARTER_RE = re.compile(r"[\u00bc\u00bd\u00be]")


def scan_turn_fraction(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (fraction, start_index, span, path_str) for each match."""
    result: list[tuple[str, int, str, str]] = []
    for m in FRACTION_SLASH_RE.finditer(text):
        result.append(("fraction", m.start(), m.group(0), path_str))
    for m in FRACTION_QUARTER_RE.finditer(text):
        result.append(("fraction", m.start(), m.group(0), path_str))
    return result
